"""Small groups as permutation groups (regular representation) and their actions on n points
(free action with fixed points allowed): vertices 0..f-1 fixed, then m orbits of size |G|."""
import itertools

def closure(gens):
    """Enumerate the group generated by permutations (tuples)."""
    idt = tuple(range(len(gens[0])))
    elems = {idt}; frontier = [idt]
    while frontier:
        new = []
        for a in frontier:
            for g in gens:
                c = tuple(g[a[i]] for i in range(len(a)))
                if c not in elems: elems.add(c); new.append(c)
        frontier = new
    return sorted(elems)

def cyc(n): return [tuple((i + 1) % n for i in range(n))]

def direct(gA, nA, gB, nB):
    # generators on nA*nB points, index a*nB+b
    out = []
    for g in gA: out.append(tuple(g[i // nB] * nB + i % nB for i in range(nA * nB)))
    for g in gB: out.append(tuple((i // nB) * nB + g[i % nB] for i in range(nA * nB)))
    return out

def dihedral(n):  # order 2n acting on 2n points? use action on Z_n x {0,1} regular: elements r^k, s r^k
    pts = [(k, e) for e in (0, 1) for k in range(n)]; idx = {p: i for i, p in enumerate(pts)}
    # left multiplication by r: r * r^k = r^{k+1}; r * s r^k = s r^{k-1}
    r = tuple(idx[((k + 1) % n, 0)] if e == 0 else idx[((k - 1) % n, 1)] for k, e in pts)
    s = tuple(idx[(k, 1 - e)] for k, e in pts)
    return [r, s]

def semidirect_cyclic(n, m, a):
    """Z_n x| Z_m with y x y^-1 = x^a (a^m = 1 mod n). Regular rep on pairs (i,j) = x^i y^j."""
    pts = [(i, j) for j in range(m) for i in range(n)]; idx = {p: t for t, p in enumerate(pts)}
    def mul(p, q):  # (x^i y^j)(x^k y^l) = x^{i + a^j k} y^{j+l}
        (i, j), (k, l) = p, q
        return ((i + pow(a, j, n) * k) % n, (j + l) % m)
    X = tuple(idx[mul((1, 0), p)] for p in pts); Y = tuple(idx[mul((0, 1), p)] for p in pts)
    return [X, Y]

def quaternion():  # Q8 regular rep via units of quaternions
    import itertools
    units = [(s, u) for u in '1ijk' for s in (1, -1)]
    tab = {('1', '1'): (1, '1'), ('1', 'i'): (1, 'i'), ('1', 'j'): (1, 'j'), ('1', 'k'): (1, 'k'),
           ('i', '1'): (1, 'i'), ('i', 'i'): (-1, '1'), ('i', 'j'): (1, 'k'), ('i', 'k'): (-1, 'j'),
           ('j', '1'): (1, 'j'), ('j', 'i'): (-1, 'k'), ('j', 'j'): (-1, '1'), ('j', 'k'): (1, 'i'),
           ('k', '1'): (1, 'k'), ('k', 'i'): (1, 'j'), ('k', 'j'): (-1, 'i'), ('k', 'k'): (-1, '1')}
    idx = {p: t for t, p in enumerate(units)}
    def mul(p, q):
        s, u = tab[(p[1], q[1])]; return (p[0] * q[0] * s, u)
    return [tuple(idx[mul((1, 'i'), p)] for p in units), tuple(idx[mul((1, 'j'), p)] for p in units)]

def dicyclic(n):  # Dic_n order 4n: <a, x | a^{2n}=1, x^2=a^n, x a x^-1 = a^-1>; elements a^i x^e
    N = 2 * n; pts = [(i, e) for e in (0, 1) for i in range(N)]; idx = {p: t for t, p in enumerate(pts)}
    def mul(p, q):
        (i, e), (k, f) = p, q
        if e == 0: return ((i + k) % N, f)
        # a^i x a^k x^f = a^{i-k} x^{1+f}; x^2 = a^n
        j = (i - k) % N
        return ((j + n) % N, 0) if f == 1 else (j, 1)
    return [tuple(idx[mul((1, 0), p)] for p in pts), tuple(idx[mul((0, 1), p)] for p in pts)]

GROUPS = {
    'Z2': (cyc(2), 2), 'Z4': (cyc(4), 4), 'Z2^2': (direct(cyc(2), 2, cyc(2), 2), 4), 'Z5': (cyc(5), 5),
    'Z8': (cyc(8), 8), 'Z4xZ2': (direct(cyc(4), 4, cyc(2), 2), 8), 'Z2^3': (direct(direct(cyc(2), 2, cyc(2), 2), 4, cyc(2), 2), 8),
    'D4': (dihedral(4), 8), 'Q8': (quaternion(), 8), 'Z10': (cyc(10), 10), 'D5': (dihedral(5), 10),
    'Z20': (cyc(20), 20), 'Z10xZ2': (direct(cyc(10), 10, cyc(2), 2), 20), 'D10': (dihedral(10), 20),
    'Dic5': (dicyclic(5), 20), 'F20': (semidirect_cyclic(5, 4, 2), 20), 'Z3': (cyc(3), 3), 'Z7': (cyc(7), 7),
    'Z13': (cyc(13), 13), 'Z6': (cyc(6), 6), 'S3': (dihedral(3), 6),
}

def action(name, n, fixed=0):
    """Generators of G acting on n points: points < fixed are fixed; rest are free orbits of size |G|."""
    gens, g = GROUPS[name]
    assert (n - fixed) % g == 0
    m = (n - fixed) // g
    assert len(closure(gens)) == g, (name, len(closure(gens)))
    out = []
    for p in gens:
        out.append([v if v < fixed else fixed + ((v - fixed) // g) * g + p[(v - fixed) % g] for v in range(n)])
    return out
